static uint8_t xt(uint8_t x){return (uint8_t)((x<<1)^((x>>7)*0x1b));}
static void add(uint8_t*s,const uint8_t*k){int i;for(i=0;i<16;i++)s[i]^=k[i];}
static void sub(uint8_t*s){int i;for(i=0;i<16;i++)s[i]=sbox[s[i]];}
static void shift(uint8_t*s){uint8_t t[16];int r,c;for(r=0;r<4;r++)for(c=0;c<4;c++)t[4*c+r]=s[4*((c+r)&3)+r];memcpy(s,t,16);}
static void mix(uint8_t*s){int c;for(c=0;c<4;c++){uint8_t*a=&s[4*c],x=a[0]^a[1]^a[2]^a[3],t=a[0];a[0]^=x^xt(a[0]^a[1]);a[1]^=x^xt(a[1]^a[2]);a[2]^=x^xt(a[2]^a[3]);a[3]^=x^xt(a[3]^t);}}
void titan_aes128_encrypt(const uint8_t key[16],const uint8_t in[16],uint8_t out[16]){uint8_t s[16],r[176],t[4];int i,n=16,round;static const uint8_t rc[10]={1,2,4,8,16,32,64,128,27,54};memcpy(s,in,16);memcpy(r,key,16);while(n<176){for(i=0;i<4;i++)t[i]=r[n-4+i];if((n&15)==0){uint8_t q=t[0];t[0]=sbox[t[1]]^rc[n/16-1];t[1]=sbox[t[2]];t[2]=sbox[t[3]];t[3]=sbox[q];}for(i=0;i<4;i++){r[n]=r[n-16]^t[i];n++;}}add(s,r);for(round=1;round<10;round++){sub(s);shift(s);mix(s);add(s,r+16*round);}sub(s);shift(s);add(s,r+160);memcpy(out,s,16);}
static void shl(const uint8_t in[16],uint8_t out[16]){int i;uint8_t carry=0;for(i=15;i>=0;i--){uint8_t v=in[i];out[i]=(uint8_t)((v<<1)|carry);carry=v>>7;}}
static void xor16(uint8_t*a,const uint8_t*b){int i;for(i=0;i<16;i++)a[i]^=b[i];}
void titan_aes_cmac(const uint8_t key[16],const uint8_t*data,unsigned len,uint8_t out[16]){uint8_t z[16]={0},l[16],k1[16],k2[16],x[16]={0},m[16];unsigned blocks=(len+15)/16,i,j;int complete=(len&&((len&15)==0));titan_aes128_encrypt(key,z,l);shl(l,k1);if(l[0]&0x80)k1[15]^=0x87;shl(k1,k2);if(k1[0]&0x80)k2[15]^=0x87;if(blocks==0)blocks=1;for(i=0;i+1<blocks;i++){for(j=0;j<16;j++)x[j]^=data[i*16+j];titan_aes128_encrypt(key,x,x);}memset(m,0,16);if(complete){memcpy(m,data+(blocks-1)*16,16);xor16(m,k1);}else{unsigned rem=len-(blocks-1)*16;if(rem)memcpy(m,data+(blocks-1)*16,rem);m[rem]=0x80;xor16(m,k2);}xor16(x,m);titan_aes128_encrypt(key,x,out);}
void titan_ble_sc_f4(const uint8_t u[32],const uint8_t v[32],const uint8_t x[16],uint8_t z,uint8_t out[16]){uint8_t m[65];memcpy(m,u,32);memcpy(m+32,v,32);m[64]=z;titan_aes_cmac(x,m,65,out);}
void titan_ble_sc_f5(const uint8_t w[32],const uint8_t n1[16],const uint8_t n2[16],const uint8_t a1[7],const uint8_t a2[7],uint8_t mackey[16],uint8_t ltk[16]){static const uint8_t salt[16]={0x6c,0x88,0x83,0x91,0xaa,0xf5,0xa5,0x38,0x60,0x37,0x0b,0xdb,0x5a,0x60,0x83,0xbe};static const uint8_t keyid[4]={'b','t','l','e'};uint8_t t[16],m[53];titan_aes_cmac(salt,w,32,t);m[0]=0;memcpy(m+1,keyid,4);memcpy(m+5,n1,16);memcpy(m+21,n2,16);memcpy(m+37,a1,7);memcpy(m+44,a2,7);m[51]=1;m[52]=0;titan_aes_cmac(t,m,53,mackey);m[0]=1;titan_aes_cmac(t,m,53,ltk);}
void titan_ble_sc_f6(const uint8_t w[16],const uint8_t n1[16],const uint8_t n2[16],const uint8_t r[16],const uint8_t iocap[3],const uint8_t a1[7],const uint8_t a2[7],uint8_t out[16]){uint8_t m[65];memcpy(m,n1,16);memcpy(m+16,n2,16);memcpy(m+32,r,16);memcpy(m+48,iocap,3);memcpy(m+51,a1,7);memcpy(m+58,a2,7);titan_aes_cmac(w,m,65,out);}
